using System;
using System.IO;
using System.Linq;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing.Editor {
public static partial class ComponentsCircuitVerification {
 static void Extra(string folder,TrialDefinition route){var s=new RaceProgressStore(folder+"/ownership.json",route);for(int i=0;i<150;i++)s.Settle(Finish(route),out _);s.BuyVehicle(Id(),"car_bastion",VehicleLineup.Find("car_bastion").price);string donor=s.Profile.fleet.selectedId;Parts(s,"induction_roots_1");string engine=FleetLedger.Find(s.Profile.fleet,donor).engineId;float boosted=WorkshopCatalog.ForBuild(s.ActiveModelId,s.ActiveWorkshop).Resolve(s.ActiveWorkshop).PeakKw();s.RemoveComponent(Id(),donor,"induction",250);string kit=s.Profile.fleet.parts.Single().id;Check(s.ActiveWorkshop.induction=="none"&&WorkshopCatalog.ForBuild(s.ActiveModelId,s.ActiveWorkshop).Resolve(s.ActiveWorkshop).PeakKw()<boosted,"Supercharger removal uses actual NA engine curve rather than a visual-only toggle");s.FitComponent(Id(),kit,donor,250);Parts(s,"induction_roots_2");Check(s.Profile.fleet.parts.Single().id==kit&&s.Profile.fleet.parts.Single().stage==2,"Paid upgrade of refitted kit advances same unit to Stage2 without creating duplicate Stage1 spare");s.BuyVehicle(Id(),"car_coda",VehicleLineup.Find("car_coda").price);string receiver=s.Profile.fleet.selectedId;Parts(s,"gearbox_3");Parts(s,"brakes_2");Parts(s,"tires_2");s.TransferEngine(Id(),donor,receiver,s.EngineTransferFee(donor,receiver));Check(s.ActiveEngineModelId=="car_bastion"&&s.Profile.fleet.parts.Single().installedEngineId==engine&&s.Profile.fleet.parts.Single().owner=="player","Whole-engine transplant carries registered fitted supercharger to coupe with same engine identity");s.RemoveComponent(Id(),receiver,"induction",250);Reject(()=>s.ComponentFitFee(kit,s.Profile.prototypeCarId),"V8 supercharger cannot fit unmatched compact engine calibration");s.FitComponent(Id(),kit,receiver,250);s.BuyReplacement(Id());string spare=s.Profile.fleet.selectedId;Parts(s,"induction_small_1");s.RemoveComponent(Id(),spare,"induction",250);string loose=s.Profile.fleet.parts.Single(p=>p.status=="stored").id;s.SelectVehicle(Id(),receiver);s.BeginDuel(Id(),"rookie","pinks");s.ForfeitDuel();Check(EngineInventoryLedger.Find(s.Profile.fleet,engine).owner=="rival"&&ComponentInventoryLedger.Find(s.Profile.fleet,kit).owner=="rival","Pink-slip title loss carries same fitted engine and registered supercharger ownership");Check(ComponentInventoryLedger.Find(s.Profile.fleet,loose).owner=="player"&&ComponentInventoryLedger.Find(s.Profile.fleet,loose).status=="stored","Loose removed turbo remains player-owned when another car is lost in pinks");var loaded=new RaceProgressStore(s.PathName,route);Check(JsonUtility.ToJson(loaded.Profile.fleet)==JsonUtility.ToJson(s.Profile.fleet),"Kit identities, engine transplant and mixed pink ownership replay after reload");var forged=JsonUtility.FromJson<RaceProgress>(File.ReadAllText(s.PathName));forged.fleet.parts.Add(JsonUtility.FromJson<PartUnit>(JsonUtility.ToJson(forged.fleet.parts[0])));string bad=folder+"/duplicate-part.json";File.WriteAllText(bad,JsonUtility.ToJson(forged));Reject(()=>new RaceProgressStore(bad,route),"Forged duplicate component registry cannot override removal/fit history");s.SelectVehicle(Id(),spare);Parts(s,"intake_1");Parts(s,"exhaust_1");int money=s.Profile.availableCredits;s.RemoveComponent(Id(),spare,"intake",75);s.RemoveComponent(Id(),spare,"exhaust",100);Check(s.Profile.availableCredits==money-175&&s.ActiveWorkshop.intakeStage==0&&s.ActiveWorkshop.exhaustStage==0,"Intake/exhaust labor removes actual installed hardware for75/100credits");}
}
}
